/// The highest desktop GLSL `#version` the test's shaders declare, if it compiles any.
///
/// A desktop `#version` cannot be compiled by an OpenGL ES context at all, so on a GLES
/// driver every desktop-shader test is untestable no matter which entry points exist.
/// Saying so up front was the difference between 11 reported errors and the 1 that was
/// actually about the driver, on an i.MX/Vivante GC2000+.
pub fn required_glsl_version(test: &str) -> Option<u32> {
    match test {
        "GL12_Textures3D" => Some(150),
        "GL14_Blend" => Some(330),
        "GL20_Uniforms" => Some(120),
        "GL20_VertexAttribs" => Some(110), // no #version directive -> GLSL 110
        "GL21_Matrices" => Some(120),
        "GL30_Advanced" => Some(130),
        "GL30_Shaders" => Some(120),
        "GL30_VBO" => Some(150),
        "GL31_UBO" => Some(140),
        "GL31_UniformBlocks" => Some(150),
        "GL32_Geometry" => Some(150),
        "GL32_Sync" => Some(150),
        "GL33_Instancing" => Some(330),
        "GL33_Packed" => Some(330),
        "GL33_VAO" => Some(330),
        "GL40_Tessellation" => Some(400),
        "GL40_TransformFeedback" => Some(400),
        "GL41_ProgramPipeline" => Some(410),
        "GL41_ProgramUniforms" => Some(410),
        "GL42_ImageLoadStore" => Some(430),
        "GL42_Storage" => Some(420),
        "GL43_Advanced" => Some(430),
        "GL43_Compute" => Some(430),
        "GL43_Debug" => Some(430),
        "GL45_DSA" => Some(450),
        "GL45_DSA_Extended" => Some(450),
        "Validate_ClearColor" => Some(110), // no #version directive -> GLSL 110
        "Validate_RenderSolid" => Some(330),
        "Validate_Compute" => Some(430),
        "Validate_Blend" => Some(330),
        _ => None,
    }
}

/// The highest `#version NNN es` the test's shaders declare, if they are GLES shaders.
///
